 26		let tasks = $state<TaskSummary[]>([]);
 27		let columns = $state<BoardColumn[]>([]);
 28		let loading = $state(true);
 29		let error = $state('');
 30		let agentStatus = $state<AgentStatus | null>(null);
 31	
 32		// AC: @ui-task-board ac-4 — Accumulated output lines per agent session
 33		const MAX_OUTPUT_LINES = 3;
 34		let agentOutputLines = $state<Record<string, string[]>>({});
 35	
 36		// AC: @ui-task-board ac-4 — Lookup map: task_ref (@ULID or @slug) → title
 37		let taskTitles = $derived(
 38			Object.fromEntries(
 39				tasks.flatMap((t) => {
 40					const entries: [string, string][] = [
 41						[`@${t._ulid}`, t.title]
 42					];
 43					for (const slug of t.slugs) {
 44						entries.push([`@${slug}`, t.title]);
 45					}
 46					return entries;
 47				})
 48			)
 49		);
