 2	  AC: @ui-task-board ac-1 — Board column container.
 3	  Renders a column header with count and contained task cards.
 4	-->
 5	<script lang="ts">
 6		import type { TaskSummary } from '@kynetic-ai/shared';
 7		import type { BoardColumn } from './board-utils';
 8		import TaskCard from './TaskCard.svelte';
 9	
10		let {
11			column,
12			onCardClick
13		}: {
14			column: BoardColumn;
15			onCardClick: (task: TaskSummary) => void;
16		} = $props();
17	</script>
18	
19	<div
20		class="flex flex-col min-w-[260px] max-w-[320px] flex-1"
21		data-testid="board-column"
22		data-column-id={column.id}
23	>
24		<!-- Column header -->
25		<div class="flex items-center gap-2 mb-3 px-1">
26			<h2 class="text-sm font-semibold">{column.label}</h2>
27			<span
28				class="inline-flex items-center justify-center min-w-[20px] h-5 rounded-full bg-muted px-1.5 text-[10px] font-medium text-muted-foreground"
29			>
30				{column.tasks.length}
31			</span>
32		</div>
33	
34		<!-- Cards -->
35		<div class="flex flex-col gap-2 overflow-y-auto flex-1 pb-4 pr-1">
36			{#if column.tasks.length === 0}
37				<div class="flex flex-col items-center justify-center py-8 text-muted-foreground text-xs text-center px-2" data-testid="column-empty">
38					{#if column.id === 'backlog'}
39						<p>No backlog tasks.</p>
40						<p class="mt-1">Create tasks with <code class="bg-muted px-1 rounded">kspec task add</code></p>
41					{:else if column.id === 'ready'}
42						<p>No tasks ready for work.</p>
43						<p class="mt-1">Mark tasks eligible with <code class="bg-muted px-1 rounded">kspec task set --automation eligible</code></p>
44					{:else if column.id === 'in_progress'}
45						<p>No active work.</p>
46						<p class="mt-1">Start a task with <code class="bg-muted px-1 rounded">kspec task start</code></p>
47					{:else if column.id === 'review'}
48						<p>Nothing awaiting review.</p>
49						<p class="mt-1">Submit work with <code class="bg-muted px-1 rounded">kspec task submit</code></p>
50					{:else if column.id === 'done'}
51						<p>No completed tasks yet.</p>
52						<p class="mt-1">Tasks appear here after completion.</p>
53					{:else}
54						<p>No tasks in this column.</p>
55					{/if}
56				</div>
57			{:else}
58				{#each column.tasks as task (task._ulid)}
59					<TaskCard {task} onclick={onCardClick} />
60				{/each}
61			{/if}
62		</div>
63	</div>

