  1	/**
  2	 * Board utility functions for Kanban column logic.
  3	 *
  4	 * AC: @ui-task-board ac-1 — Column distribution logic
  5	 */
  6	
  7	import type { TaskSummary } from '@kynetic-ai/shared';
  8	
  9	export type ColumnId = 'backlog' | 'ready' | 'in_progress' | 'review' | 'done';
 10	
 11	export interface BoardColumn {
 12		id: ColumnId;
 13		label: string;
 14		tasks: TaskSummary[];
 15	}
 16	
 17	/**
 18	 * Status color mapping using design system tokens.
 19	 * Returns both bg and fg CSS variable references.
 20	 */
 21	export function getStatusClasses(status: string): { bg: string; fg: string; label: string } {
 22		const map: Record<string, { bg: string; fg: string; label: string }> = {
 23			pending: {
 24				bg: 'bg-status-pending',
 25				fg: 'text-status-pending-fg',
 26				label: 'Pending'
 27			},
 28			in_progress: {
 29				bg: 'bg-status-in-progress',
 30				fg: 'text-status-in-progress-fg',
 31				label: 'In Progress'
 32			},
 33			pending_review: {
 34				bg: 'bg-status-pending-review',
 35				fg: 'text-status-pending-review-fg',
 36				label: 'Review'
 37			},
 38			needs_work: {
 39				bg: 'bg-status-needs-work',
 40				fg: 'text-status-needs-work-fg',
 41				label: 'Needs Work'
 42			},
 43			completed: {
 44				bg: 'bg-status-completed',
 45				fg: 'text-status-completed-fg',
 46				label: 'Completed'
 47			},
 48			blocked: {
 49				bg: 'bg-status-blocked',
 50				fg: 'text-status-blocked-fg',
 51				label: 'Blocked'
 52			},
 53			cancelled: {
 54				bg: 'bg-status-cancelled',
 55				fg: 'text-status-cancelled-fg',
 56				label: 'Cancelled'
 57			}
 58		};
 59		return map[status] || { bg: 'bg-muted', fg: 'text-muted-foreground', label: status };
 60	}
 61	
 62	/**
 63	 * Distribute tasks into Kanban columns.
 64	 *
 65	 * AC: @ui-task-board ac-1
 66	 * - Backlog: pending + manual_only or unassessed automation
 67	 * - Ready: pending + eligible automation
 68	 * - In Progress: in_progress + needs_work
 69	 * - Review: pending_review
 70	 * - Done: completed (recent — last 20)
 71	 *
 72	 * Blocked and cancelled are indicators on individual cards, not separate columns.
 73	 */
 74	export function distributeToColumns(tasks: TaskSummary[]): BoardColumn[] {
 75		const backlog: TaskSummary[] = [];
 76		const ready: TaskSummary[] = [];
 77		const inProgress: TaskSummary[] = [];
 78		const review: TaskSummary[] = [];
 79		const done: TaskSummary[] = [];
 80	
 81		for (const task of tasks) {
 82			switch (task.status) {
 83				case 'pending': {
 84					const auto = task.automation;
 85					if (auto === 'eligible') {
 86						ready.push(task);
 87					} else {
 88						// manual_only, unassessed, or undefined → backlog
 89						backlog.push(task);
 90					}
 91					break;
 92				}
 93				case 'in_progress':
 94				case 'needs_work':
 95					inProgress.push(task);
 96					break;
 97				case 'pending_review':
 98					review.push(task);
 99					break;
100				case 'completed':
101					done.push(task);
102					break;
103				case 'blocked':
